    39→public class PlayerUtils
    40→{
    41→    /**
    42→     * 誰が見てるのかわかるやつ。
    43→     *
    44→     * @param player 見られてるプレイヤー。
    45→     * @return 見てるプレイヤー。
    46→     */
    47→    public static Player getLookingEntity(Player player)
    48→    {
    49→        for (Location location : player.getLineOfSight(null, 4).parallelStream().map(Block::getLocation)
    50→            .collect(Collectors.toCollection(ArrayList::new)))
    51→            for (Entity entity : player.getNearbyEntities(3.5, 3.5, 3.5))
    52→                if (isLooking((Player) entity, location) && entity.getType() == EntityType.PLAYER)
    53→                    return (Player) entity;
    54→
    55→        return null;
    56→    }
    57→
    58→    /**
    59→     * 今見てるかわかるやつ。
    60→     *
    61→     * @param player   見られてるプレイヤー。
    62→     * @param location あと場所。
    63→     * @return 見られてたらtrue。
    64→     */
    65→    public static boolean isLooking(Player player, Location location)
    66→    {
    67→        BlockIterator it = new BlockIterator(player, 4);
    68→
    69→        while (it.hasNext())
    70→        {
    71→            final Block block = it.next();
    72→            if (block.getX() == location.getBlockX() &&
    73→                block.getY() == location.getBlockY() &&
    74→                block.getZ() == location.getBlockZ())
    75→                return true;
    76→        }
    77→        return false;
    78→    }
