    84→     * @return クリティカル警察が反応したらtrueを返してくれます。
    85→     */
    86→    public static boolean hasCritical(Player player)
    87→    {
    88→        return player.getFallDistance() > 0.0F &&
    89→            !player.getLocation().getBlock().isLiquid() &&
    90→            !player.isOnGround() &&
    91→            !player.hasPotionEffect(PotionEffectType.BLINDNESS) &&
    92→            player.getVehicle() == null;
    93→    }
