   101→    public static EntityPlayer getRandomPlayer(World world)
   102→    {
   103→        Random random = new Random();
   104→        String first = random.nextBoolean()
   105→            ? RandomStringUtils.randomAlphanumeric(new Random().nextInt(13) + 1)
